INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_340', 'en_u6_l4', 'He took her cubs, and ran up the mountain without looking back.', 'Dia mengambil anak-anaknya, dan berlari ke gunung tanpa menoleh ke belakang.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_341', 'en_u6_l4', 'The Dusun language will be launched on Google Translate in 2018.', 'Bahasa Dusun akan dilancarkan di Google Translate pada tahun 2018.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
