INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_343', 'en_u6_l4', 'Tom speaks Dusun to Mary, because Mary is a Kadazan from Penampang.', 'Tom bercakap bahasa Dusun kepada Mary, kerana Mary berbangsa Kadazan dari Penampang.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_344', 'en_u6_l4', 'It''s a good rule to look both ways before you cross the street anywhere.', 'Ialah sebuah peraturan yang bagus untuk melihat dua-dua arah sebelum melintasi jalan raya di mana-mana sahaja.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_345', 'en_u6_l4', 'It was very cold last night, so we didn''t go outside, but stayed indoors.', 'Semalam sangat sejuk, jadi kami tidak keluar dan hanya duduk di rumah.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
