INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_348', 'en_u6_l4', 'After rounding the Dragon''s Tooth, the wind was on our side, and we were flying. It felt like we were running twice as fast.', 'Selepas mengelilingi Dragon''s Tooth, angin telah menyebelahi kami, dan kami telah terbang. Ia terasa seperti kami memecut dua kali lagi laju.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO lessons (id, unit_id, title, description, order_index) VALUES ('en_u6_l5', 'en_unit_6', 'Weather & Nature 5', 'Real sentence practice: weather & nature (Tatoeba CC-BY).', 4) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, description = EXCLUDED.description, order_index = EXCLUDED.order_index;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('en_card_349', 'en_u6_l5', 'She smiled.', 'Dia senyum', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
