INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_317', 'fr_u6_l2', 'Pendant l''hiver je dors avec deux couvertures.', 'During winter I sleep with two blankets.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_318', 'fr_u6_l2', 'Le seigle était appelé le grain de la pauvreté.', 'Rye was called the grain of poverty.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_319', 'fr_u6_l2', 'On pouvait voir le coucher du soleil depuis la fenêtre.', 'We could see the sunset from the window.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_320', 'fr_u6_l2', 'Je vais m''asseoir sur le banc là-bas, près du lampadaire.', 'I''m going to sit on the bench over there next to the street lamp.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_321', 'fr_u6_l2', 'La vie est une maladie mortelle sexuellement transmissible.', 'Life is a fatal sexually transmitted disease.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_322', 'fr_u6_l2', 'J''habite près de la mer donc j''ai souvent l''occasion d''aller à la plage.', 'I live near the sea, so I often get to go to the beach.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_323', 'fr_u6_l2', 'Lorsque j''ai la migraine, l''aspirine ne soulage pas la douleur pour moi.', 'When I have migraines, aspirin doesn''t alleviate the pain for me.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_324', 'fr_u6_l2', 'J''avais prévu d''aller à la plage aujourd''hui, mais il a commencé à pleuvoir.', 'I was planning on going to the beach today, but then it started to rain.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO lessons (id, unit_id, title, description, order_index) VALUES ('fr_u6_l3', 'fr_unit_6', 'Weather & Nature 3', 'Real sentence practice: weather & nature (Tatoeba CC-BY).', 2) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, description = EXCLUDED.description, order_index = EXCLUDED.order_index;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_325', 'fr_u6_l3', 'Si l''on savait ce que l''on faisait, ça ne s''appellerait pas de la recherche, non ?', 'If we knew what we were doing, it wouldn''t be called research, would it?', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_326', 'fr_u6_l3', 'Quand on commence à ressembler à la photo de son passeport, on devrait partir en vacances.', 'When you''re beginning to look like the photo in your passport, you should go on a holiday.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_327', 'fr_u6_l3', 'Les escrocs tirent avantage de la crédulité des investisseurs inexpérimentés et leur soutirent de l''argent.', 'Con artists take advantage of the credulity of inexperienced investors and swindle them out of their money.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_328', 'fr_u6_l3', 'Vous connaissez la phrase, « on récolte ce que l’on sème. » Moi, j’ai semé le vent, maintenant voilà ma tempête.', 'You know the phrase, we reap what we sow. I have sown the wind and this is my storm.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_329', 'fr_u6_l3', 'Si tu ne veux pas mettre de crème solaire c''est ton problème, mais ne viens pas te plaindre quand t''auras des coups de soleil.', 'If you don''t want to put on sunscreen, that''s your problem. Just don''t come complaining to me when you get a sunburn.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_330', 'fr_u6_l3', 'Même maintenant, des années après la Guerre Froide, il y a encore beaucoup de rancoeur entre les Russes et les Allemands, en particulier dans les régions autrefois occupées par l''Union Soviétique.', 'Even now, many years after the Cold War, there is still much rancor between the Russians and the Germans, especially in areas once occupied by the Soviet Union.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_331', 'fr_u6_l3', 'Ne perdez jamais de vue l''importance d''un beau lever de soleil, ou de regarder vos enfants dormir, ou de l''odeur de la pluie. Ce sont souvent les petites choses qui importent vraiment dans la vie.', 'Never lose sight of the importance of a beautiful sunrise, or watching your kids sleep, or the smell of rain. It''s often the small things that really matter in life.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
