INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_399', 'fr_u7_l4', 'Le passé peut être seulement connu, pas changé. Le futur peut être seulement changé, pas connu.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_400', 'fr_u7_l4', 'On ne peut que connaître le passé, pas le changer. On ne peut que changer le futur, pas le connaître.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_401', 'fr_u7_l4', 'Le gouvernement français a lancé un jeu en ligne qui défie les contribuables d''équilibrer le budget national.', 'The French government has launched an online game that challenges taxpayers to balance the national budget.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_402', 'fr_u7_l4', 'Ce n''est pas l''espèce la plus forte qui survit, pas la plus intelligente, mais celle qui est la plus réactive au changement.', 'It is not the strongest of the species that survives, not the most intelligent, but the one most responsive to change.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_403', 'fr_u7_l4', 'La publicité peut être décrite comme la science de stopper l''intelligence humaine assez longtemps pour en tirer de l''argent.', 'Advertising may be described as the science of arresting the human intelligence long enough to get money from it.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_404', 'fr_u7_l4', 'Mon colocataire ne regarde pas à la dépense quand il s''agit de cinéma : il achète les films le jour de leur sortie, quel que soit le prix.', 'My roommate is prodigal when it comes to spending money on movies; he buys them the day they''re released, regardless of price.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_405', 'fr_u7_l4', 'De nos jours dans les affaires, trop des cadres dépensent de l''argent qu''ils n''ont pas gagné, pour acheter des choses dont ils n''ont pas besoin, pour impressionner des gens qu''ils n''aiment même pas.', 'In business today, too many executives spend money they haven''t earned, to buy things they don''t need, to impress people they don''t even like.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
