INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_471', 'fr_u8_l5', 'Dans les années 50, on citait les Finnois comme ayant les régimes alimentaires les moins sains du monde.', 'In the 1950''s, the Finns were cited as having one of the least healthy diets in the world.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
