INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('fr_card_476', 'fr_u8_l5', 'Si on lève un sourcil, ça peut signifier « J''ai envie d''avoir des relations sexuelles avec toi » mais aussi « Je trouve que ce que tu viens de dire est complètement idiot. »', 'If you raise an eyebrow, it can mean "I want to have sex with you", but also "I find that what you just said is completely idiotic."', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
