INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_337', 'es_u6_l4', 'Incluso ahora, muchos años después de la Guerra Fría, todavía hay mucho rencor entre los rusos y los alemanes, especialmente en las zonas que fueron ocupadas por la Unión Soviética.', 'Even now, many years after the Cold War, there is still much rancor between the Russians and the Germans, especially in areas once occupied by the Soviet Union.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_338', 'es_u6_l4', 'Nunca olvides la importancia de un bonito amanecer, o de ver a tus hijos dormir, o del olor de la lluvia. Muchas veces las cosas pequeñas son las que importan realmente en esta vida.', 'Never lose sight of the importance of a beautiful sunrise, or watching your kids sleep, or the smell of rain. It''s often the small things that really matter in life.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
