INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_397', 'es_u7_l4', 'América es un lugar encantador para vivir, si estás aquí para ganar dinero.', 'America is a lovely place to be, if you are here to earn money.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_398', 'es_u7_l4', 'Es una pena que no puedas comprar milagros de la misma forma que compras patatas.', 'It''s a pity that you can''t buy miracles like you would buy potatoes.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_399', 'es_u7_l4', 'Si piensas que la educación es cara, espera a ver lo que te cuesta la ignorancia.', 'If you think education is expensive, wait till you see what ignorance costs you.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_400', 'es_u7_l4', 'El pasado lo podemos conocer pero no cambiar. El futuro lo podemos cambiar pero no conocer.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_401', 'es_u7_l4', 'El pasado sólo puede conocerse, no cambiarse. El futuro sólo puede cambiarse, no conocerse.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_402', 'es_u7_l4', 'El pasado sólo puede ser conocido, no cambiado. El futuro sólo puede ser cambiado, no conocido.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_403', 'es_u7_l4', 'No es la especie más fuerte la que sobrevive, ni la más inteligente, sino la que sabe responder mejor al cambio.', 'It is not the strongest of the species that survives, not the most intelligent, but the one most responsive to change.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('es_card_404', 'es_u7_l4', 'La publicidad se puede describir como la ciencia de interrumpir la inteligencia humana el tiempo suficiente para conseguir así dinero.', 'Advertising may be described as the science of arresting the human intelligence long enough to get money from it.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
