INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_319', 'zh_u6_l2', '蠢人一下子就把箭射完。', 'A fool''s bolt is soon shot.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_320', 'zh_u6_l2', '你很快就會習慣這種冷天氣。', 'You''ll soon get accustomed to this cold weather.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_321', 'zh_u6_l2', '強風暗示著即將到來的暴雨。', 'The strong wind indicates that a storm is coming.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_322', 'zh_u6_l2', '恐懼永遠都是由無知所造成的。', 'Fear always springs from ignorance.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_323', 'zh_u6_l2', '我覺得在寒冷的早晨很難早起。', 'I find it hard to get up early on cold mornings.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_324', 'zh_u6_l2', '气压计下降了 - 要下雨了。', 'The barometer is falling. It is going to rain.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO lessons (id, unit_id, title, description, order_index) VALUES ('zh_u6_l3', 'zh_unit_6', 'Weather & Nature 3', 'Real sentence practice: weather & nature (Tatoeba CC-BY).', 2) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, description = EXCLUDED.description, order_index = EXCLUDED.order_index;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_325', 'zh_u6_l3', '从天上看下来，这条河像一条巨蛇。', 'Seen from the sky, the river looked like a huge snake.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_326', 'zh_u6_l3', '當天氣變冷的時候，我的關節疼痛。', 'My joints ache when it gets cold.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_327', 'zh_u6_l3', '我會在那盞街燈旁邊的長凳上坐下來。', 'I''m going to sit on the bench over there next to the street lamp.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_328', 'zh_u6_l3', '我们走的时候下着雨，到的时候有太阳。', 'It was raining when we left, but by the time we arrived, it was sunny.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_329', 'zh_u6_l3', '灰暗的天空突然下起了一大滴一大滴的雨來。', 'All of a sudden, large drops of rain began falling from the dark sky.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_330', 'zh_u6_l3', '月球表面沒有空氣，所以沒有風，也沒有聲音。', 'Without air there can be no wind or sound on the moon.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_331', 'zh_u6_l3', '溫迪的確是在海邊長大的，但是她卻不太會游泳。', 'It is true Wendy grew up at the seaside, but she isn''t a good swimmer.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_332', 'zh_u6_l3', '我本来预备今天去海滩的，但接着天就开始下雨了。', 'I was planning on going to the beach today, but then it started to rain.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_333', 'zh_u6_l3', '当我们开始像自己护照上的照片时，我们该去度假了。', 'When you''re beginning to look like the photo in your passport, you should go on a holiday.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_334', 'zh_u6_l3', '我很庆幸我们没有去那儿，因为当时那儿有局部大暴雨。', 'I''m glad we didn''t go there because there were some localized heavy rain showers.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_335', 'zh_u6_l3', '如果我们知道我们在做什么，那么这不能称之为研究，是吗？', 'If we knew what we were doing, it wouldn''t be called research, would it?', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_336', 'zh_u6_l3', '雖然冷戰已經過了這麼多年，俄羅斯人和德國人之間的仇恨還是沒有消除，在蘇聯曾經侵佔過的地區，這種仇恨就更深了。', 'Even now, many years after the Cold War, there is still much rancor between the Russians and the Germans, especially in areas once occupied by the Soviet Union.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO lessons (id, unit_id, title, description, order_index) VALUES ('zh_u6_l4', 'zh_unit_6', 'Weather & Nature 4', 'Real sentence practice: weather & nature (Tatoeba CC-BY).', 3) ON CONFLICT (id) DO UPDATE SET unit_id = EXCLUDED.unit_id, title = EXCLUDED.title, description = EXCLUDED.description, order_index = EXCLUDED.order_index;
