INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('zh_card_479', 'zh_u8_l5', '「你累的話怎麼不去睡覺？」「因為我現在去睡的話，就會太早醒過來了。」', '"If you''re tired, why don''t you go to sleep?" "Because if I go to sleep now I will wake up too early."', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
