INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ja_card_234', 'ja_u4_l5', '一緒に暮らせる誰かと結婚するのではなく、その人なしでは生きていけない人と結婚するのよ。', 'You don''t marry someone you can live with — you marry the person whom you cannot live without.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
