INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_229', 'ru_u4_l5', 'Сара была достаточно проницательна, чтобы понять, что её друзья пытаются её разыграть.', 'Sarah was discerning enough to realize that her friends were trying to prank her.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_230', 'ru_u4_l5', 'Люди охотнее примут вашу идею, если вы скажете, что первым её озвучил Бенджамин Франклин.', 'People will accept your idea much more readily if you tell them Benjamin Franklin said it first.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_231', 'ru_u4_l5', 'В мире есть 10 типов людей: те, кто понимает двоичную систему счисления, и те, кто не понимает.', 'There are 10 types of people in the world: those who understand binary, and those who don''t.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_232', 'ru_u4_l5', 'Если ты дал взаймы кому-нибудь 20 долларов и больше не видишь этого человека, вероятно, оно того стоило.', 'If you lend someone $20 and never see that person again, it was probably worth it.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_233', 'ru_u4_l5', 'Его отец никогда бы не одобрил его помолвку с девушкой, которая не разделяет те же религиозные убеждения, что и их семья.', 'His father would never sanction his engagement to a girl who did not share the same religious beliefs as their family.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
