INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_402', 'ru_u7_l4', 'Прошлое можно только знать, но не изменять. Будущее можно только изменять, но не знать.', 'The past can only be known, not changed. The future can only be changed, not known.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
