INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_472', 'ru_u8_l5', 'Она притворяется спящей. Вот почему она не храпит.', 'She''s faking sleep. That''s why she''s not snoring.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_473', 'ru_u8_l5', 'Я могу коснуться ладонями пола, не сгибая коленей.', 'I can place the palms of my hands on the floor without bending my knees.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_474', 'ru_u8_l5', 'Для твоего же здоровья тебе бы лучше бросить курить.', 'You had better give up smoking for your health.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_475', 'ru_u8_l5', 'Я не хочу провести остаток своей жизни, сожалея об этом.', 'I don''t want to spend the rest of my life regretting it.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_476', 'ru_u8_l5', 'Ты выглядишь уставшей. Тебе необходимо отдохнуть час или два.', 'You look tired. You ought to rest for an hour or two.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_477', 'ru_u8_l5', 'Ты выглядишь уставшим. Тебе необходимо отдохнуть час или два.', 'You look tired. You ought to rest for an hour or two.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_478', 'ru_u8_l5', 'В 1950-х писалось, что в мире диета финнов — одна из наименее полезных.', 'In the 1950''s, the Finns were cited as having one of the least healthy diets in the world.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_479', 'ru_u8_l5', '«Если ты устала, почему ты не пойдёшь спать?» — «Потому что если я пойду спать сейчас, я проснусь слишком рано».', '"If you''re tired, why don''t you go to sleep?" "Because if I go to sleep now I will wake up too early."', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ru_card_480', 'ru_u8_l5', 'Если ты поднимаешь бровь, это может значить "Я хочу переспать с тобой", а также "Я думаю, то, что ты сказал сейчас, полная чушь".', 'If you raise an eyebrow, it can mean "I want to have sex with you", but also "I find that what you just said is completely idiotic."', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
