INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ms_card_345', 'ms_u6_l4', 'Tom bercakap bahasa Dusun kepada Mary, kerana Mary berbangsa Kadazan dari Penampang.', 'Tom speaks Dusun to Mary, because Mary is a Kadazan from Penampang.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
