INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ms_card_391', 'ms_u7_l3', 'Afghanistan dan Iran sudah menukarkan lagu kebangsaan mereka beberapa kali semasa abad ke-20.', 'Afghanistan and Iran both changed their national anthems several times in the course of the 20th century.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
