INSERT INTO flashcards (id, lesson_id, front_text, back_text, context_sentence, audio_url) VALUES ('ms_card_393', 'ms_u7_l3', 'Aku takkan berjanji akan menunggu kau, tapi bila kita memang berjodoh, aku yakin hati kau dan hati aku takkan berubah sampai kita dipertemukan kembali.', 'I will not promise to wait for you, but if we are married, I am sure your heart and my heart will not change until we meet again.', NULL, NULL) ON CONFLICT (id) DO UPDATE SET lesson_id = EXCLUDED.lesson_id, front_text = EXCLUDED.front_text, back_text = EXCLUDED.back_text, context_sentence = EXCLUDED.context_sentence, audio_url = EXCLUDED.audio_url;
